 static final class Entry {final String pkg,label,protection;final boolean installed,enabled;Entry(String p,String l,String why,boolean i,boolean e){pkg=p;label=l;protection=why;installed=i;enabled=e;}}
 protected void onCreate(Bundle b){appearance=Ui.prepare(this);super.onCreate(b);Ui.bars(this);prefs=new SettingsStore(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(Ui.dp(this,24),Ui.dp(this,16),Ui.dp(this,24),Ui.dp(this,12));Ui.backdrop(this,root);setContentView(root);TextView title=Ui.label(this,Ui.word(this,"Системные приложения","System apps"),22);root.addView(title);TextView help=Ui.label(this,Ui.word(this,"ADB удаляет установки всех профилей. Удаление заводского APK — отдельная root-операция для доступной на запись прошивки.","ADB removes installations for all profiles. Factory APK deletion is a separate root operation on writable firmware."),14);help.setTextColor(Ui.muted(this));help.setPadding(0,Ui.dp(this,8),0,Ui.dp(this,8));root.addView(help);
  LinearLayout buttons=new LinearLayout(this);for(String name:new String[]{Ui.word(this,"Подключение","Connection"),Ui.word(this,"Обновить список","Refresh")}){Button button=Ui.tvButton(this,name);LinearLayout.LayoutParams buttonSize=new LinearLayout.LayoutParams(0,Ui.dp(this,48),1);if(buttons.getChildCount()==0)buttonSize.rightMargin=Ui.dp(this,8);buttons.addView(button,buttonSize);if(buttons.getChildCount()==1)button.setOnClickListener(v->connection());else button.setOnClickListener(v->reload());}root.addView(buttons);status=Ui.label(this,"",14);status.setTextColor(Ui.muted(this));root.addView(status);
  search=new EditText(this);search.setSingleLine();search.setTextColor(Ui.ink(this));search.setHintTextColor(Ui.muted(this));search.setTextSize(18);search.setHint(Ui.word(this,"Поиск по названию или пакету","Search name or package"));root.addView(search,new LinearLayout.LayoutParams(-1,Ui.dp(this,48)));removed=new CheckBox(this);removed.setText(Ui.word(this,"Показывать удалённые установки","Show removed installations"));removed.setTextColor(Ui.ink(this));root.addView(removed);count=Ui.label(this,"",13);root.addView(count);
  list=new ListView(this);if(Build.VERSION.SDK_INT>=26)list.setDefaultFocusHighlightEnabled(false);list.setCacheColorHint(android.graphics.Color.TRANSPARENT);list.setSelector(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));list.setOnFocusChangeListener((view,focused)->list.setSelector(focused?Ui.selector(this):new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT)));list.setAdapter(new BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int p){return shown.get(p);}public long getItemId(int p){return p;}public View getView(int p,View reuse,ViewGroup parent){ExpertRow row=reuse instanceof ExpertRow?(ExpertRow)reuse:new ExpertRow(ExpertActivity.this);Entry e=shown.get(p);String state=Ui.word(ExpertActivity.this,!e.installed?"Не установлено для пользователя":e.enabled?"Включено":"Отключено",!e.installed?"Removed for user":e.enabled?"Enabled":"Disabled");row.title.setText(e.label);row.detail.setText(e.pkg+" · "+state+(e.protection==null?"":"\n"+e.protection));row.title.setTextColor(!e.installed?Ui.muted(ExpertActivity.this):e.enabled?Ui.ink(ExpertActivity.this):Ui.DISABLED_RED);row.detail.setTextColor(e.installed&&!e.enabled?Ui.DISABLED_RED:Ui.muted(ExpertActivity.this));AppCatalog.get(ExpertActivity.this).image(e.pkg,row.icon);return row;}});root.addView(list,new LinearLayout.LayoutParams(-1,0,1));list.setOnItemClickListener((parent,v,p,id)->actions(shown.get(p)));removed.setOnCheckedChangeListener((v,value)->filter());search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int n,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){filter();}public void afterTextChanged(Editable e){}});if(b!=null){search.setText(b.getString("query",""));removed.setChecked(b.getBoolean("removed"));}getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);updateStatus();reload();
 }
