  ExpertRow(Context c){super(c);setGravity(Gravity.CENTER_VERTICAL);setPadding(Ui.dp(c,12),Ui.dp(c,8),Ui.dp(c,12),Ui.dp(c,8));FrameLayout image=new FrameLayout(c);Glyph fallback=new Glyph(c,"apps");fallback.setAlpha(.35f);image.addView(fallback,new FrameLayout.LayoutParams(Ui.dp(c,24),Ui.dp(c,24),Gravity.CENTER));icon=new ImageView(c);icon.setScaleType(ImageView.ScaleType.FIT_CENTER);image.addView(icon,new FrameLayout.LayoutParams(-1,-1));addView(image,new LinearLayout.LayoutParams(Ui.dp(c,40),Ui.dp(c,40)));LinearLayout text=new LinearLayout(c);text.setOrientation(1);title=Ui.label(c,"",16);text.addView(title);detail=Ui.label(c,"",13);detail.setPadding(0,Ui.dp(c,2),0,0);text.addView(detail);LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(0,-2,1);size.leftMargin=Ui.dp(c,12);addView(text,size);}
